"""Preview the exact imported frames and licensed audio used by the Windows build."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
manifest=json.loads((ROOT/'Client/Assets/Game/Art/Presentation/manifest.json').read_text(encoding='utf-8'))
catalog=json.loads((ROOT/'GameData/mvp-catalog.json').read_text(encoding='utf-8'))
audio=json.loads((ROOT/'Client/Assets/Game/Audio/Combat-v86/manifest.json').read_text(encoding='utf-8'))
textures={t['path']:t for t in manifest['textures']}
def actor(id):
    a=next(a for a in manifest['actors'] if a['id']==id)
    clips={c['motion']:{**c,'frames':[{'url':'../../../Client/'+p,'pivot':textures[p]['pivot']} for p in c['frames']]} for c in a['clips'] if c['motion'] in ('Idle','Attack','Hit','Stun')}
    return {k:a[k] for k in ['id','facesRight','height','referenceHeightPixels']}|{'clips':clips}
stages=[]
for s in catalog['stages'][:20]:
    enemy=next(e for e in catalog['enemies'] if e['id']==s['enemyId'])
    stages.append(dict(stage=s['number'],name=enemy['displayName'],kind=s['kind'],actor=actor(enemy['artId'])))
cards=''
for r in audio['files']:
    cards+=f'<article><h3>{html.escape(r["label"])}</h3><audio controls preload="none" src="../../../Client/Assets/Game/Audio/Combat-v86/{r["file"]}"></audio><p>{r["durationSeconds"]:.2f}초 · {html.escape(r["creator"])} · CC0</p><a href="{r["sourceUrl"]}">원본·라이선스</a></article>'
page=r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Last Bell v8.6 · 적 20종과 새 사운드</title><style>
@font-face{font-family:neo;src:url('../../../Client/Assets/Game/Art/Fonts/NeoDunggeunmoPro-Regular.ttf')}*{box-sizing:border-box}body{margin:0;background:#0c1922;color:#eee1bd;font-family:neo,monospace;line-height:1.7}main{max-width:1280px;padding:30px 24px;margin:auto}h1{font-size:30px}h2{font-size:23px;margin-top:40px}h3{font-size:18px;margin:8px 0}p{color:#afc3c5}a{color:#ecc073}nav,.row{display:flex;flex-wrap:wrap;gap:18px}.lead{border-left:4px solid #e7b563;padding-left:20px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}article{background:#142933;border:1px solid #35515b;padding:16px}audio{max-width:100%;width:100%}button,select{font:inherit;background:#203942;color:#f1dfb5;border:1px solid #7c9395;padding:9px 15px;cursor:pointer}.controls{position:sticky;top:0;background:#0c1922ee;padding:14px 0;z-index:2}canvas{width:100%;height:auto;image-rendering:pixelated}.badge{color:#e7b563}.small{font-size:13px}.shots{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.shots img{width:100%}.demo{position:relative;overflow:hidden;min-height:100px}.ring{position:absolute;top:50%;left:50%;border:3px solid #a5e8d5;border-radius:50%;width:10px;height:10px;pointer-events:none;animation:wave .6s ease-out forwards}@keyframes wave{to{transform:translate(-50%,-50%) scale(90);opacity:0}}@media(max-width:850px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.grid,.shots{grid-template-columns:1fr}}
</style><main><span class="badge">LAST BELL / v8.6</span><h1>스테이지마다 새로운 상대</h1><p class="lead">1~20스테이지 적 20종을 한 번씩 배치했습니다. 성 밖은 서로 다른 야생동물, 성 안은 기존 도트 몬스터를 살렸습니다.<br>종 효과음은 제거하고, 밝은 칩튠과 짧은 공격·회피음으로 교체했습니다.</p>
<nav><a href="../../../Builds/Windows/LastBellMvp.exe">Windows 실행</a><a href="../../../Builds/LastBellMvp-Windows.zip">공유 ZIP</a><a href="../../Evidence/Feedback-v86/verification.json">검증 기록</a><a href="#sound">음원 듣기</a><a href="../../../Client/Assets/StreamingAssets/AudioLicenses/CREDITS.txt">출처·편집 내역</a></nav>
<h2 id="sound">밝은 도트 사운드</h2><p>배경음: Juhani Junkala의 4 Chiptunes (Adventure). 원곡의 속도와 반복 구간을 유지했습니다.<br>회피는 입력이 받아들여지는 순간 1회 재생합니다. 완벽 판정 때 종이나 회피음을 추가로 겹치지 않습니다. 아래 음원은 단독 원음량이며, 게임에서는 BGM 20~24%, 공격 75%, 회피 65%로 믹스됩니다.</p>
<div class="grid">__AUDIO__</div><article class="demo" id="demo"><h3>일반·완벽 회피 비교</h3><div class="row"><button id="normal">일반 회피음</button><button id="perfect">완벽 회피음 + 파동</button></div><p class="small">같은 회피음입니다. 완벽 회피는 기존 화면 중앙 파동과 반격 기회로 구분합니다. 이 영역은 소리 비교용이며 게임의 판정을 재현하지 않습니다.</p></article>
<h2>1~20 스테이지 · 중복 없는 배치</h2><p>모든 카드는 게임에 연결된 PNG·피벗·프레임 시간을 그대로 사용합니다. 왼쪽의 온은 상대 크기를 확인하는 기준입니다. 피격은 현재 모습 위의 흰색 플래시입니다.</p>
<div class="controls row"><label>모션 <select id="motion"><option>Idle</option><option>Attack</option><option>Stun</option><option>Hit</option></select></label><button id="pause">일시정지</button><label>속도 <select id="speed"><option value="1">1×</option><option value=".5">0.5×</option></select></label></div><div class="grid" id="roster"></div>
<h2>실제 게임 화면</h2><div class="shots"><img src="../../Evidence/Feedback-v86/desktop/v83-stage-04.png" alt="성 밖 여우 전투"><img src="../../Evidence/Feedback-v86/desktop/v83-stage-15.png" alt="주거구 사슬 집행자 전투"></div><p>캐릭터 선택 Idle, 로비·조작키 배치, 강화·유물·체크포인트 및 전투 판정 규칙은 유지했습니다.</p></main>
<script>const stages=__STAGES__,hero=__HERO__;const images=new Map();for(const a of [hero,...stages.map(s=>s.actor)])for(const c of Object.values(a.clips))for(const f of c.frames){if(!images.has(f.url)){const i=new Image;i.src=f.url;images.set(f.url,i)}}const motion=document.querySelector('#motion');let paused=false,elapsed=0,last=performance.now();document.querySelector('#pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'재생':'일시정지'};motion.onchange=()=>elapsed=0;
const cards=stages.map(s=>{const el=document.createElement('article');el.innerHTML=`<span class="badge">STAGE ${s.stage} · ${s.stage<=10?'성 밖':'주거구'}${s.kind==='boss'?' · 보스':''}</span><h3>${s.name}</h3><canvas width="400" height="260"></canvas><p class="small"></p>`;document.querySelector('#roster').append(el);return {s,canvas:el.querySelector('canvas'),meta:el.querySelector('p')}});
function sample(c,t){const holds=c.frameDurationsMs?.length===c.frames.length?c.frameDurationsMs:c.frames.map(()=>1000/(c.fps||8));const total=holds.reduce((a,b)=>a+b,0);t=t%(total+(c.loop?0:500));if(!c.loop)t=Math.min(t,total-1);let n=0;while(n<holds.length-1&&t>=holds[n])t-=holds[n++];return c.frames[n]}
const flashes=new Map();function draw(ctx,a,m,t,x,y){const c=a.clips[m==='Hit'?'Idle':m]||a.clips.Idle,f=sample(c,t),im=images.get(f.url);if(!im?.complete||!im.naturalWidth)return;const scale=a.height/(c.referenceHeightPixels||a.referenceHeightPixels)/.008611111*.48;ctx.save();ctx.translate(x,y);if(a.id!=='hero_on'&&a.facesRight)ctx.scale(-1,1);ctx.drawImage(im,-f.pivot.x*scale,-f.pivot.y*scale,im.width*scale,im.height*scale);if(m==='Hit'&&t%900<100){if(!flashes.has(f.url)){let cv=document.createElement('canvas');cv.width=im.width;cv.height=im.height;let fc=cv.getContext('2d');fc.drawImage(im,0,0);fc.globalCompositeOperation='source-in';fc.fillStyle='#fff';fc.fillRect(0,0,cv.width,cv.height);flashes.set(f.url,cv)}ctx.drawImage(flashes.get(f.url),-f.pivot.x*scale,-f.pivot.y*scale,im.width*scale,im.height*scale)}ctx.restore()}
function frame(now){if(!paused)elapsed+=(now-last)*Number(document.querySelector('#speed').value);last=now;for(const {s,canvas,meta} of cards){const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.fillStyle='#142933';ctx.fillRect(0,0,400,260);ctx.fillStyle='#3b5961';ctx.fillRect(0,235,400,2);draw(ctx,hero,'Idle',elapsed,45,235);draw(ctx,s.actor,motion.value,elapsed,260,235);const c=s.actor.clips[motion.value]||s.actor.clips.Idle;meta.textContent=motion.value==='Hit'?'현재 모습 + 흰색 플래시':`${motion.value} · ${c.frames.length}프레임 · ${c.frameDurationsMs?.reduce((a,b)=>a+b,0)||Math.round(c.frames.length/(c.fps||8)*1000)}ms${c.loop?' 반복':''}`;}requestAnimationFrame(frame)}requestAnimationFrame(frame);
const dodge=new Audio('../../../Client/Assets/Game/Audio/Combat-v86/dodge-air.wav');dodge.volume=.65;function play(perfect){dodge.currentTime=0;dodge.play();if(perfect){const el=document.createElement('i');el.className='ring';document.querySelector('#demo').append(el);setTimeout(()=>el.remove(),650)}}document.querySelector('#normal').onclick=()=>play(false);document.querySelector('#perfect').onclick=()=>play(true);for(const a of document.querySelectorAll('audio'))a.addEventListener('play',()=>{for(const b of document.querySelectorAll('audio'))if(a!==b)b.pause()});
</script></html>'''
page=page.replace('__AUDIO__',cards).replace('__STAGES__',json.dumps(stages,ensure_ascii=False)).replace('__HERO__',json.dumps(actor('hero_on'),ensure_ascii=False))
target=ROOT/'Planning/Reference/TimingHero-20261023/feedback-v86.html'
target.write_text(page,encoding='utf-8');print(target)
